-- Career module (cv.extract wiring): what `cv-extract` reported besides the structured CV. ADR-0005 §4 has
-- the injection flags of every model output reach the owner, so they are persisted with the draft. Additive
-- only: four nullable/defaulted columns on `cv_bases`.

-- AlterTable (generated by `prisma migrate diff`)
ALTER TABLE "cv_bases" ADD COLUMN     "generation" JSONB,
ADD COLUMN     "injection_evidence" TEXT,
ADD COLUMN     "injection_suspected" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "parse_warnings" JSONB;

-- Hand-written invariants
-- The excerpt is bounded (the store cuts it) and only exists together with the flag.
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_injection_evidence_check"
  CHECK ("injection_evidence" IS NULL OR ("injection_suspected" AND char_length("injection_evidence") BETWEEN 1 AND 500));
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_parse_warnings_check"
  CHECK ("parse_warnings" IS NULL OR jsonb_typeof("parse_warnings") = 'array');
ALTER TABLE "cv_bases" ADD CONSTRAINT "cv_bases_generation_check"
  CHECK ("generation" IS NULL OR jsonb_typeof("generation") = 'object');
